\begin{lemma}\label{lem:qld-4-12}
	For all $x,z \in \F_q^m$ and $\alpha,\beta \in \F_q$ and $\mH \in \{ \mH_\alice, \mH_\bob\}$ there exists a projective measurement $\{ \hat{Q}^{x,z,\alpha,\beta}_c \}_{c \in \F_q}$ acting on $\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ such that the following holds:
	\begin{enumerate}
		\item (\textbf{Self-consistency}) On average over uniformly random $(x,z,\alpha,\beta) \in \F_q^{2m + 2}$:
		\begin{equation}
			\label{eq:qld-4-12-self-cons}
			(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\alice \alice'} \approx_{\delta_Q}  (\hat{Q}^{x,z,\alpha,\beta}_{c})_{\bob \alice''}\,.
		\end{equation}
\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly random $(x,z,\alpha,\beta) \in \F_q^{2m + 2}$:
		\begin{gather}
			\label{eq:qld-4-12-cons-m-hat}
			(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\alice \alice'} \approx_{\delta_Q} \Big ( \sum_{\substack{a,b: \\ \alpha a + \beta b = c}} \hat{M}^{(\Point,X),x}_{a} \hat{M}^{(\Point,Z),z}_{b} \Big )_{\bob \alice''} \;, \\
			\label{eq:qld-4-12-cons-m-hat2}
			(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\alice \alice'} \approx_{\delta_Q}  \Big ( \sum_{\substack{a,b: \\ \alpha a + \beta b = c}} \hat{M}^{(\Point,Z),z}_{b} \, \hat{M}^{(\Point,X),x}_{a}  \Big )_{\bob \alice''}  \,.			
		\end{gather}
              \end{enumerate}
                    Furthermore, all symmetric equivalents of these approximations
      also hold.
\end{lemma}
\begin{proof}
	Define 
	\[
		\hat{Q}^{x,z,\alpha,\beta}_{c} = \sum_{\substack{a,b:\\ \alpha a + \beta b = c}} \hat{Q}^{x,z}_{a,b}.
	\]
	The self-consistency and consistency properties of $\{ \hat{Q}^{x,z,\alpha,\beta}_{c} \}$ follow from the consistency properties of $\{ \hat{Q}^{x,z}_{a,b} \}$ established by Lemma~\ref{lem:qld-4-10}, and Fact~\ref{fact:data-processing}. 
\end{proof}

	\lean{MIPStarRE.QPBT.ProjectiveSetting.tauPointMeas_effect}
	\leanok
	\uses{def:expanded-point-measurement}
	The ancillary point measurement at $W\in\{X,Z\}$ and $u\in\F_q^m$
	is the POVM $\{\tau^{W,u}_{a''}\}_{a''\in\F_q}$ on one Pauli
	register. It is obtained by measuring the generalized Pauli basis
	and reporting $a''=h\cdot\mathrm{ind}_m(u)$. Its effects are
	positive and sum to the identity, since the fibres of this map
	partition the Pauli basis labels.
\end{definition}

\begin{definition}[Product of strategy and ancillary point measurements]
	\label{def:point-tau-measurement}
	\lean{MIPStarRE.QPBT.ProjectiveSetting.pointTauMeas}
	\lean{MIPStarRE.QPBT.ProjectiveSetting.pointTauMeas_effect}
	\leanok
	\uses{def:ancillary-point-measurement, def:strategy-observables}
	For either player, the product measurement on the strategy register
	and one Pauli register has separate outcomes $(a',a'')\in\F_q^2$
	and effects
	\[
	N^{W,u}_{a',a''}
	=M^{(\mathrm{Point},W),u}_{a'}\otimes\tau^{W,u}_{a''}.
	\]
	This auxiliary measurement records the two outcomes whose sum defines
	the expanded point outcome. Tensor products preserve positivity, and
	completeness of both factors gives $\sum_{a',a''}N^{W,u}_{a',a''}=\Id$.
\end{definition}

\begin{lemma}[Convolution and projectivity of expanded point measurements]
	\label{lem:expanded-point-measurement-properties}
